using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class DelegationInquiryTests
{
    static WorldSession New(bool refuses=false,long until=long.MaxValue)=>new(DelegationMission.Create(refuses:refuses,until:until));
    static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);var before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    static EntityId Send(WorldSession s){var r=DelegationMission.Build(s.DiagnosticSnapshot(),"request:inquiry-target",RegionalAction.Move);Assert.Equal(ResultCode.Accepted,s.IssueRegional(r,s.Revision).Code);return r.Id;}
    static long Due(WorldSession s,string message)=>MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,message).DueAt;
    static string Order(WorldSession s)=>s.DiagnosticSnapshot().Region!.Commands.Single().Message;
    static long ArrivalAt(WorldSession s)=>s.DiagnosticSnapshot().Delegation!.Plans.Single().Units.SelectMany(u=>u.Route).Select(l=>l.EndAt).Max();
    static DelegationQuestion Question(EntityId target,bool destination=true,string id="request:inquiry")=>new(new(id),target,destination);
    static void Ask(WorldSession s,DelegationQuestion q)=>Assert.Equal(ResultCode.Accepted,s.QueryDelegation(q,s.PlayerControl,s.Revision).Code);
    static string Reply(WorldSession s)=>s.DiagnosticSnapshot().Messaging.Messages.Last(m=>m.Kind==DelegationInquiry.ReplyKind).Id;
    static EntityId MissedArrival(WorldSession s){var target=Send(s);At(s,Due(s,Order(s)));At(s,ArrivalAt(s));var m=s.DiagnosticSnapshot().Delegation!.Arrivals.Single().Message;s.DiagnosticTransport((flow,t)=>MessageFlow.Fail(flow,m));At(s,Due(s,m));return target;}
    [Fact] public void InquiryCannotMoveOrReexecuteUnits(){var s=New();var target=MissedArrival(s);var before=s.DiagnosticSnapshot().Region!.Units;var plans=s.DiagnosticSnapshot().Delegation!.Plans;var q=Question(target);Ask(s,q);At(s,Due(s,DelegationInquiry.MessageId(q.Id)));Assert.Equal(ContractJson.Write(before),ContractJson.Write(s.DiagnosticSnapshot().Region!.Units));Assert.Equal(ContractJson.Write(plans),ContractJson.Write(s.DiagnosticSnapshot().Delegation!.Plans));Assert.Single(s.DiagnosticSnapshot().Delegation!.Arrivals);}
    [Fact] public void UnknownReplyStaysInvisibleUntilPhysicalReturn(){var s=New();var target=MissedArrival(s);var q=Question(target);Ask(s,q);At(s,Due(s,DelegationInquiry.MessageId(q.Id)));var row=DelegationInquiry.View(s,s.PlayerControl).Single();Assert.Null(row.Progress);Assert.Equal("照会発送済・返答未確認",row.State);Assert.Equal("到達の返報は未確認",DelegationMission.View(s,s.PlayerControl).Single().Progress);At(s,Due(s,Reply(s)));Assert.Equal("照会返答を受領",DelegationInquiry.View(s,s.PlayerControl).Single().State);Assert.Equal("配置到達の申告",DelegationMission.View(s,s.PlayerControl).Single().Progress);}
    [Fact] public void QuotedReportDoesNotForgeReceiptOfLostOriginal(){var s=New();var target=MissedArrival(s);var report=s.DiagnosticSnapshot().Delegation!.Arrivals.Single();var q=Question(target);Ask(s,q);At(s,Due(s,DelegationInquiry.MessageId(q.Id)));At(s,Due(s,Reply(s)));var w=s.DiagnosticSnapshot();Assert.False(MessageFlow.Knows(w.Messaging,report.Message,s.PlayerControl.Value));Assert.DoesNotContain(w.Messaging.Receipts,r=>r.MessageId==report.Message);Assert.False(DelegationInquiry.View(s,s.PlayerControl).Single().OriginalReceived);var views=RegionalBattle.View(w,s.PlayerControl).Where(v=>DelegationMission.Units.Contains(v.Unit)).ToArray();Assert.Equal(3,views.Length);Assert.All(views,v=>{Assert.Equal(report.At,v.ObservedAt);Assert.False(v.Live);});}
    [Fact] public void PlannedAddressIsNotLiveTracking(){var s=New();var target=Send(s);Ask(s,Question(target));var w=s.DiagnosticSnapshot();var d=w.Region!.Deliveries.Single(d=>w.Messaging.Attempts.Single(a=>a.Id==d.Attempt).MessageId==DelegationInquiry.MessageId(new("request:inquiry")));Assert.Equal(w.Region.Commands.Single().Request.A,d.Address);Assert.NotEqual(w.Region.Units.First(u=>u.Commander==ContractFixture.Clerk).Position,d.Address);}
    [Fact] public void LostQuestionOnlyBecomesKnownThroughFailureReturn(){var s=New();var target=MissedArrival(s);var q=Question(target);Ask(s,q);var m=DelegationInquiry.MessageId(q.Id);s.DiagnosticTransport((flow,t)=>MessageFlow.Fail(flow,m));At(s,Due(s,m));Assert.DoesNotContain(s.DiagnosticSnapshot().Messaging.Messages,m=>m.Kind==DelegationInquiry.ReplyKind);Assert.Equal("照会発送済・返答未確認",DelegationInquiry.View(s,s.PlayerControl).Single().State);var a=MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,m);var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&m.Body==a.Id);At(s,Due(s,f.Id));Assert.Equal("照会不達の報告を受領",DelegationInquiry.View(s,s.PlayerControl).Single().State);}
    [Fact] public void LostAnswerDoesNotInventKnowledge(){var s=New();var target=MissedArrival(s);var q=Question(target);Ask(s,q);At(s,Due(s,DelegationInquiry.MessageId(q.Id)));string reply=Reply(s);s.DiagnosticTransport((flow,t)=>MessageFlow.Fail(flow,reply));At(s,Due(s,reply)+200);Assert.Null(DelegationInquiry.View(s,s.PlayerControl).Single().Progress);Assert.Equal("到達の返報は未確認",DelegationMission.View(s,s.PlayerControl).Single().Progress);}
    [Fact] public void UnreceivedOriginalIsNotKnownByAskedOfficer(){var s=New();var target=Send(s);s.DiagnosticTransport((flow,t)=>MessageFlow.Fail(flow,Order(s)));var q=Question(target,false);Ask(s,q);At(s,Due(s,DelegationInquiry.MessageId(q.Id)));At(s,Due(s,Reply(s)));Assert.Equal("unrecognized",DelegationInquiry.View(s,s.PlayerControl).Single().Receipt);Assert.Equal("命令をまだ認識していない申告",DelegationInquiry.View(s,s.PlayerControl).Single().Progress);Assert.Empty(s.DiagnosticSnapshot().Delegation!.Plans);}
    [Fact] public void DuplicateQuestionDoesNotCreateAnotherCourier(){var s=New();var target=Send(s);var q=Question(target);Ask(s,q);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.QueryDelegation(q,s.PlayerControl,0).Code);Assert.Equal(bytes,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.IdPayloadConflict,s.QueryDelegation(q with{Destination=false},s.PlayerControl,s.Revision).Code);}
    [Fact] public void NoImpersonationOrUnissuedDirective(){var s=New();var target=Send(s);Assert.Equal(ResultCode.NotAvailable,s.QueryDelegation(Question(target),ContractFixture.Clerk,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.QueryDelegation(Question(new("request:unknown")),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.QueryDelegation(Question(target),s.PlayerControl,0).Code);}
    [Fact] public void ExpiredAuthorityDoesNotPreventInformationRequest(){var s=New(until:5);var target=Send(s);At(s,Due(s,Order(s)));var q=Question(target,false);Ask(s,q);At(s,Due(s,DelegationInquiry.MessageId(q.Id)));At(s,Due(s,Reply(s)));Assert.Equal("authority-refused",DelegationInquiry.View(s,s.PlayerControl).Single().Receipt);Assert.Empty(s.DiagnosticSnapshot().Delegation!.Plans);}
    [Fact] public void RefusalRemainsAnOfficerClaimNotAnAutomaticPunishment(){var s=New(true);var target=Send(s);At(s,Due(s,Order(s)));var q=Question(target,false);Ask(s,q);At(s,Due(s,DelegationInquiry.MessageId(q.Id)));At(s,Due(s,Reply(s)));Assert.Equal("refused",DelegationInquiry.View(s,s.PlayerControl).Single().Receipt);Assert.Equal("責任・処分は未審査",DelegationMission.View(s,s.PlayerControl).Single().Responsibility);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(20)][InlineData(50)][InlineData(200)]
    public void SaveAndContinuePreserveQuestionReplyAndKnowledge(int delta){var s=New();var target=MissedArrival(s);Ask(s,Question(target));At(s,s.Seconds+delta);s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"delegation-query-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));At(s,s.Seconds+350);At(host.Current,s.Seconds);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(DelegationInquiry.View(s,s.PlayerControl),DelegationInquiry.View(host.Current,host.Current.PlayerControl));}
    [Theory][InlineData("time")][InlineData("arrival")][InlineData("sender")][InlineData("address")]
    public void ForgedReplyOrQuestionCannotLoad(string kind){var s=New();var target=MissedArrival(s);Ask(s,Question(target));At(s,Due(s,DelegationInquiry.MessageId(new("request:inquiry"))));var w=s.DiagnosticSnapshot();var m=w.Messaging.Messages.Single(m=>m.Kind==DelegationInquiry.ReplyKind);var a=ContractJson.Read<DelegationAnswer>(System.Text.Encoding.UTF8.GetBytes(m.Body));if(kind=="time")a=a with{At=w.ElapsedSeconds+1};if(kind=="arrival")a=a with{Arrival="message:nonexistent"};w.Messaging.Messages=w.Messaging.Messages.Select(x=>x.Id==m.Id?x with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(a)),SenderId=kind=="sender"?w.PlayerControl.Value:x.SenderId}:x).ToArray();if(kind=="address"){var d=w.Region!.Deliveries.Single(d=>w.Messaging.Attempts.Single(a=>a.Id==d.Attempt).MessageId==m.Id);w.Region=w.Region with{Deliveries=w.Region.Deliveries.Select(x=>x.Attempt==d.Attempt?x with{Address=new(0,0)}:x).ToArray()};}Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void StoppedOwnUnitsAreReportedWithoutAssigningBlame(){var s=New();var target=Send(s);At(s,Due(s,Order(s)));var w=s.DiagnosticSnapshot();w.Region=w.Region! with{Units=w.Region.Units.Select(u=>DelegationMission.Units.Contains(u.Id)?u with{RouteOrigin=u.Position,Route=[],Goal=u.Position,Phase="blocked"}:u).ToArray()};RegionalBattle.Sync(w);s=new(w);var q=Question(target,false);Ask(s,q);At(s,Due(s,DelegationInquiry.MessageId(q.Id)));At(s,Due(s,Reply(s)));Assert.Equal("通行・接触により停止の申告",DelegationInquiry.View(s,s.PlayerControl).Single().Progress);Assert.Empty(s.DiagnosticSnapshot().Delegation!.Arrivals);Assert.Equal("責任・処分は未審査",DelegationMission.View(s,s.PlayerControl).Single().Responsibility);}
    [Fact] public void QuotedOldArrivalCannotReplaceNewerDirectKnowledge(){var s=New();var target=MissedArrival(s);var q=Question(target);Ask(s,q);At(s,Due(s,DelegationInquiry.MessageId(q.Id)));At(s,Due(s,Reply(s)));var w=s.DiagnosticSnapshot();var r=w.Delegation!.Arrivals.Single();var unit=r.Units[0];var direct=new RegionalView(unit.Unit,unit.Position,unit.Heading,RegionalGround.Height(unit.Position,true,true),unit.Soldiers,unit.Morale,"standing",s.Seconds,true);var result=DelegationMission.MergeReports(w,s.PlayerControl,[direct]);Assert.Equal(direct,result.Single(v=>v.Unit==direct.Unit));}

}
